// Define start date of week 1 (Tuesday before season opener)
const seasonStart = new Date('2025-09-02T00:00:00-04:00'); // Eastern Time
const now = new Date();

// Calculate difference in days
const diffDays = Math.floor((now - seasonStart) / (1000 * 60 * 60 * 24));

// Calculate current NFL week (1-indexed)
let currentWeek = Math.floor(diffDays / 7) + 1;

// Safety clamp: NFL regular season has 18 weeks
if (currentWeek < 1) currentWeek = 1;
if (currentWeek > 18) currentWeek = 18;

// If it's Tuesday before Sportradar updates, bump to next week
// (Assumes run time ~2 AM Tuesday)
if (now.getDay() === 2 && now.getHours() < 6) {
  currentWeek += 1;
}

// Build your Sportradar URL
const url = `https://api.sportradar.com/ncaafb/trial/v7/en/games/2025/REG/${currentWeek +1}/schedule.json`;

return { url, currentWeek };
